49: TEST_CASE("toString(Tag) maps known tags and formats unknown tags") {
50:   CHECK(toString(Tag::ImageWidth) == "ImageWidth");
51:   CHECK(toString(Tag::PhotometricInterpretation) == "PhotometricInterpretation");
52:   CHECK(toString(Tag::Null) == "Null");
53:   CHECK(toString(static_cast<Tag>(0xFFFF)) == "0xFFFF");
54: }
55: 
56: TEST_CASE("toString(Type) maps every type and formats unknown types") {
57:   CHECK(toString(Type::BYTE) == "BYTE");
58:   CHECK(toString(Type::ASCII) == "ASCII");
59:   CHECK(toString(Type::SHORT) == "SHORT");
60:   CHECK(toString(Type::LONG) == "LONG");
61:   CHECK(toString(Type::RATIONAL) == "RATIONAL");
62:   CHECK(toString(Type::SBYTE) == "SBYTE");
63:   CHECK(toString(Type::UNDEFINED) == "UNDEFINED");
64:   CHECK(toString(Type::SSHORT) == "SSHORT");
65:   CHECK(toString(Type::SLONG) == "SLONG");
66:   CHECK(toString(Type::SRATIONAL) == "SRATIONAL");
67:   CHECK(toString(Type::FLOAT) == "FLOAT");
68:   CHECK(toString(Type::DOUBLE) == "DOUBLE");
69:   CHECK(toString(static_cast<Type>(0xFFFF)) == "!UNKNOWN");
70: }
